mapper.select:
SELECT order_id, tenant_id, warehouse_id, reference_type, reference_id, status, remark, created_at, updated_at
FROM wms_inbound_order WHERE tenant_id = #{tenantId} AND warehouse_id = #{warehouseId}
ORDER BY created_at DESC

SELECT order_id, tenant_id, warehouse_id, reference_type, reference_id, status, remark, created_at, updated_at
FROM wms_outbound_order WHERE tenant_id = #{tenantId} AND warehouse_id = #{warehouseId}
ORDER BY created_at DESC

SELECT package_id, tenant_id, order_id, warehouse_id, carrier_code, tracking_no,
       weight_kg, status, remark, packed_at, shipped_at, created_at, updated_at
FROM wms_outbound_package WHERE tenant_id = #{tenantId} AND package_id = #{packageId}

SELECT movement_id, tenant_id, warehouse_id, seller_sku, from_location_id, to_location_id, quantity, type, reference_type, reference_id, moved_at
FROM wms_inventory_movement WHERE tenant_id = #{tenantId} AND warehouse_id = #{warehouseId}
ORDER BY moved_at DESC

SELECT check_id, tenant_id, warehouse_id, inbound_order_id, seller_sku, sample_quantity, pass_quantity, fail_quantity, result, inspector, remark, checked_at, created_at
FROM wms_quality_check WHERE tenant_id = #{tenantId} AND warehouse_id = #{warehouseId}
ORDER BY checked_at DESC

SELECT check_id, tenant_id, warehouse_id, inbound_order_id, seller_sku, sample_quantity, pass_quantity, fail_quantity, result, inspector, remark, checked_at, created_at
FROM wms_quality_check WHERE tenant_id = #{tenantId} AND inbound_order_id = #{inboundOrderId}
ORDER BY checked_at DESC

SELECT return_id, tenant_id, warehouse_id, po_id, supplier_id, seller_sku, quantity, reason,
       supplier_reply, status, processed_by, remark, processed_at, created_at, updated_at
FROM wms_defective_return WHERE tenant_id = #{tenantId} AND return_id = #{returnId}

SELECT return_id, tenant_id, warehouse_id, po_id, supplier_id, seller_sku, quantity, reason,
       supplier_reply, status, processed_by, remark, processed_at, created_at, updated_at
FROM wms_defective_return
WHERE tenant_id = #{tenantId}
  AND warehouse_id = #{warehouseId}
  AND seller_sku = #{sellerSku}
  AND status = 'PENDING'
ORDER BY created_at DESC

SELECT repair_id, tenant_id, warehouse_id, supplier_id, seller_sku, outbound_quantity, inbound_quantity,
       reason, status, qc_result, processed_by, remark, completed_at, created_at, updated_at
FROM wms_product_repair WHERE tenant_id = #{tenantId} AND repair_id = #{repairId}
